const p="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const q="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge";
const cmds=[
 ["chain",`rg -n --glob '*.lean' '\\b(canonicalRankOneAbelIso|rankOneAbelIso|pic0_representableBy)\\b' '${p}/AlgebraicJacobian' '${q}/AlgebraicJacobian'`],
 ["datum",`rg -n --glob '*.lean' '(structure|def|theorem|noncomputable def).*\\b(PicRepDatum|JacobianData)\\b|\\b(PicRepDatum|JacobianData)\\b.*:=' '${p}/AlgebraicJacobian/Picard' '${p}/AlgebraicJacobian/Challenge.lean' '${q}/AlgebraicJacobian'`],
 ["open",`rg -n --glob '*.lean' '\\bPicRankOneOpen\\b|rankOne.*[Ii]sOpen|IsOpen.*rankOne|\\bIsOpen\\b' '${p}/AlgebraicJacobian/Picard/Pic0RankOne'* '${p}/AlgebraicJacobian/Picard/DivRankOneOpen'* '${p}/AlgebraicJacobian/Picard/DivSchemeRedesignRankOne'*`],
 ["challengefiles",`rg --files '${p}' '${q}' | rg '(^|/)(Challenge|AlgebraicJacobian|Jacobian|Pic0CriticalPath|PicRepDatum|JacobianDataFromPicRepDatum)\\.lean$'`]
];
const rs=await Promise.all(cmds.map(async([n,cmd])=>[n,await tools.exec_command({cmd,workdir:p,yield_time_ms:10000,max_output_tokens:20000})]));
for(const [n,r] of rs) text(`--- ${n} ---\n${r.output}`);
